---
const { title = 'Ferryx Docs' } = Astro.props;
---

<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width" />
    <title>{title} · Ferryx Docs</title>
  </head>
  <body>
    <header><a href="/">Ferryx Docs</a></header>
    <div class="shell">
      <aside>
        <nav aria-label="Documentation">
          <a href="/">Introduction</a>
          <a href="/shortcuts/">Shortcuts</a>
        </nav>
      </aside>
      <main><slot /></main>
    </div>
  </body>
</html>

<style>
  :global(*) { box-sizing: border-box; }
  :global(body) { margin: 0; background: #09090b; color: #f4f4f5; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; line-height: 1.7; }
  header { border-bottom: 1px solid #27272a; padding: 1.25rem max(1.5rem, calc((100vw - 1080px) / 2)); }
  header a { color: #f4f4f5; font-weight: 700; text-decoration: none; }
  .shell { display: grid; grid-template-columns: 210px minmax(0, 700px); gap: 4rem; max-width: 1080px; margin: 0 auto; padding: 3rem 1.5rem; }
  aside { border-right: 1px solid #27272a; }
  nav { display: grid; gap: .5rem; position: sticky; top: 2rem; }
  nav a { color: #a1a1aa; text-decoration: none; }
  nav a:hover, nav a:focus { color: #f4f4f5; }
  main { min-width: 0; }
  :global(h1) { margin: 0 0 1.5rem; font-size: 2rem; letter-spacing: -.04em; }
  :global(h2) { margin: 2.5rem 0 1rem; font-size: 1.15rem; }
  :global(p) { color: #a1a1aa; }
  :global(a) { color: #d4d4d8; }
  :global(table) { width: 100%; border-collapse: collapse; }
  :global(th), :global(td) { border-bottom: 1px solid #27272a; padding: .7rem .5rem; text-align: left; }
  :global(th) { color: #71717a; font-size: .75rem; text-transform: uppercase; }
  :global(td:first-child) { width: 40%; }
  :global(kbd) { background: #18181b; border: 1px solid #3f3f46; border-radius: .25rem; color: #f4f4f5; padding: .15rem .4rem; white-space: nowrap; }
  @media (max-width: 700px) { .shell { display: block; padding-top: 2rem; } aside { border: 0; margin-bottom: 2.5rem; } nav { position: static; display: flex; gap: 1.25rem; } }
</style>

